-- Latest-items widget (#810): type 'items', bound to a published model like
-- 'measure'. Each check is dropped and added in one statement.
ALTER TABLE "dashboard_widgets" DROP CONSTRAINT "dashboard_widgets_type_valid", ADD CONSTRAINT "dashboard_widgets_type_valid" CHECK ("dashboard_widgets"."type" in ('metric', 'line', 'bar', 'image', 'text', 'clock', 'table', 'status', 'compare', 'countdown', 'gauge', 'review', 'measure', 'items'));--> statement-breakpoint
ALTER TABLE "dashboard_widgets" DROP CONSTRAINT "dashboard_widgets_model_valid", ADD CONSTRAINT "dashboard_widgets_model_valid" CHECK (case when "dashboard_widgets"."type" in ('measure', 'items') then "dashboard_widgets"."model_id" is not null and "dashboard_widgets"."model_binding" is not null when "dashboard_widgets"."type" = 'compare' then ("dashboard_widgets"."model_id" is null) = ("dashboard_widgets"."model_binding" is null) else "dashboard_widgets"."model_id" is null and "dashboard_widgets"."model_binding" is null end);
